function buildFileGlobRowSpec(): WidgetSpec {
  if (!panel) return col();
  return row(
    spacer(1),
    textInput(panel.fileGlob, {
      label: editor.t("panel.files_label"),
      focused: false,
      cursorByte: -1,
      fieldWidth: 54,
      key: "fileGlobField",
